<?php require_once 'includes/functions.php';require_login();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT q.*,c.name category,(SELECT COUNT(*) FROM questions WHERE quiz_id=q.id) question_count FROM quizzes q JOIN categories c ON c.id=q.category_id WHERE q.id=? AND q.is_published=1");$s->execute([$id]);$q=$s->fetch();if(!$q){http_response_code(404);exit('Quiz not found.');}
$s=db()->prepare('SELECT COUNT(*) FROM attempts WHERE user_id=? AND quiz_id=?');$s->execute([user()['id'],$id]);$attempts=(int)$s->fetchColumn();$canAttempt=$attempts===0||$q['allow_retakes'];$pageTitle='Quiz Instructions';require 'includes/header.php';?>
<section class="form-card wide"><span class="badge"><?=e($q['category'])?></span><h1><?=e($q['title'])?></h1><p><?=e($q['description'])?></p><h2>Quiz Rules</h2><ul><li>Total questions: <strong><?=$q['question_count']?></strong></li><li>Time limit: <strong><?=$q['time_limit_minutes']?> minutes</strong></li><li>Select one answer for each question.</li><li>The quiz submits automatically when time finishes.</li><li>Unanswered questions receive zero marks.</li></ul><?php if($canAttempt&&$q['question_count']):?><a class="button" href="quiz.php?id=<?=$q['id']?>"><?=$attempts?'Retake Quiz':'Start Quiz'?></a><?php elseif(!$q['question_count']):?><p class="error">This quiz has no questions yet.</p><?php else:?><p class="error">Retakes are not allowed for this quiz.</p><?php endif;?></section>
<?php require 'includes/footer.php';?>
